import numpy as np
from qiskit import QuantumCircuit
from qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager
from qiskit_ibm_runtime.fake_provider import FakeSherbrooke

backend = FakeSherbrooke()
target = backend.target
ecr_error = {tuple(q): p.error for q, p in target["ecr"].items() if p is not None and p.error is not None}
readout_error = {q[0]: p.error for q, p in target["measure"].items() if p is not None and p.error is not None}
t1 = np.array([backend.qubit_properties(q).t1 for q in range(backend.num_qubits)]) * 1e6        # microseconds
t2 = np.array([backend.qubit_properties(q).t2 for q in range(backend.num_qubits)]) * 1e6
print("calibration snapshot date:", backend.properties().last_update_date.date(), "(stored with the fake backend, not live)")
print(f"qubits {backend.num_qubits}; two-qubit gate error: best {min(ecr_error.values()):.4f}, median {np.median(list(ecr_error.values())):.4f}, worst {max(ecr_error.values()):.4f}")
print(f"readout error: best {min(readout_error.values()):.4f}, median {np.median(list(readout_error.values())):.4f}, worst {max(readout_error.values()):.4f}")
print(f"T1 median {np.median(t1):.0f} us, T2 median {np.median(t2):.0f} us; T2 <= 2 T1 holds for every qubit: {bool(np.all(t2 <= 2 * t1 + 1e-9))}")

neighbours = {q: set() for q in range(backend.num_qubits)}
for a, b in ecr_error:
    neighbours[a].add(b)
def paths(length):
    def extend(path):
        if len(path) == length:
            yield tuple(path)
            return
        for nxt in neighbours[path[-1]]:
            if nxt not in path:
                yield from extend(path + [nxt])
    for start in range(backend.num_qubits):
        yield from extend([start])
def cost(path):
    gates = sum(min(ecr_error.get((a, b), 1), ecr_error.get((b, a), 1)) for a, b in zip(path, path[1:]))
    return gates + sum(readout_error[q] for q in path)

best = min(paths(5), key=cost)
worst = max(paths(5), key=cost)
print("best 5-qubit path:", best, f"cost {cost(best):.4f}", "| worst:", worst, f"cost {cost(worst):.4f}", f"-> {cost(worst) / cost(best):.1f}x worse")

ghz = QuantumCircuit(5); ghz.h(0); ghz.cx(0, 1); ghz.cx(1, 2); ghz.cx(2, 3); ghz.cx(3, 4); ghz.measure_all()
chosen = generate_preset_pass_manager(optimization_level=1, backend=backend, seed_transpiler=3).run(ghz)
index = lambda instruction: tuple(chosen.find_bit(q).index for q in instruction.qubits)
edges_used = {index(i) for i in chosen.data if i.operation.name == "ecr"}
measured = {index(i)[0] for i in chosen.data if i.operation.name == "measure"}
transpiler_cost = sum(min(ecr_error.get(e, 1), ecr_error.get(e[::-1], 1)) for e in edges_used) + sum(readout_error[q] for q in measured)
print("transpiler's automatic choice: couplings", sorted(edges_used), f"cost {transpiler_cost:.4f}", "(same formula: gate errors on the couplings used plus readout errors of the measured qubits)")
print(f"ratio of the transpiler's choice to the best path found by search: {transpiler_cost / cost(best):.2f}")

from qiskit import QuantumCircuit
from qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager
from qiskit_aer import AerSimulator
from qiskit_aer.noise import NoiseModel
from qiskit_ibm_runtime.fake_provider import FakeSherbrooke

backend = FakeSherbrooke()
noise_model = NoiseModel.from_backend(backend)
print("noisy instructions in the model:", sorted(noise_model.noise_instructions))
noisy = AerSimulator.from_backend(backend, seed_simulator=11)
ideal = AerSimulator(seed_simulator=11)

target = backend.target
ecr_error = {tuple(q): p.error for q, p in target["ecr"].items() if p is not None and p.error is not None}
readout_error = {q[0]: p.error for q, p in target["measure"].items() if p is not None and p.error is not None}
neighbours = {q: set() for q in range(backend.num_qubits)}
for a, b in ecr_error:
    neighbours[a].add(b)

def best_path(length):                                                 # the path of connected qubits with the lowest summed gate and readout error
    def extend(path):
        if len(path) == length:
            yield tuple(path)
            return
        for nxt in neighbours[path[-1]]:
            if nxt not in path:
                yield from extend(path + [nxt])
    cost = lambda path: sum(min(ecr_error.get((a, b), 1), ecr_error.get((b, a), 1)) for a, b in zip(path, path[1:])) + sum(readout_error[q] for q in path)
    return min((p for start in range(backend.num_qubits) for p in extend([start])), key=cost)

def ghz(n):
    qc = QuantumCircuit(n)
    qc.h(0)
    for q in range(n - 1):
        qc.cx(q, q + 1)                                              # a chain: fits the device topology
    qc.measure_all()
    return qc

def population(simulator, circuit, shots=4000):
    counts = simulator.run(circuit, shots=shots).result().get_counts()
    width = len(next(iter(counts)))                                     # number of measured bits (a transpiled circuit has 127 qubits but only n clbits)
    return (counts.get("0" * width, 0) + counts.get("1" * width, 0)) / shots

def worst_coupler(isa):
    edges = [tuple(isa.find_bit(q).index for q in i.qubits) for i in isa.data if i.operation.name == "ecr"]
    return max(ecr_error.get(e, ecr_error.get(e[::-1], 0)) for e in edges)

print(f"{'qubits':<7} {'ideal':>6} {'automatic layout: worst coupler error':>38} {'population':>11} {'searched best path: worst coupler error':>40} {'population':>11}")
for n in (3, 5, 7, 9):
    automatic = generate_preset_pass_manager(optimization_level=1, backend=backend, seed_transpiler=5).run(ghz(n))
    chosen = generate_preset_pass_manager(optimization_level=1, backend=backend, seed_transpiler=5, initial_layout=list(best_path(n))).run(ghz(n))
    print(f"{n:<7} {population(ideal, ghz(n)):>6.3f} {worst_coupler(automatic):>38.4f} {population(noisy, automatic):>11.3f} {worst_coupler(chosen):>40.4f} {population(noisy, chosen):>11.3f}")
